using Grpc.Core;
using Library.Contracts;
using Library.Service.Data;
using Library.Service.Domain;
using Microsoft.EntityFrameworkCore;
using Google.Protobuf.WellKnownTypes;

namespace Library.Service.Services;

public sealed class LibraryRpcService(LibraryDbContext db, ILogger<LibraryRpcService> logger) : LibraryRpc.LibraryRpcBase
{
 public override async Task<BookReply> CreateBook(CreateBookRequest r, ServerCallContext c) {
  if(string.IsNullOrWhiteSpace(r.Title)||string.IsNullOrWhiteSpace(r.Author)) throw Invalid("Title and author are required.");
  if(r.Pages<=0) throw Invalid("Pages must be greater than zero."); if(r.Copies<0) throw Invalid("Copies cannot be negative.");
  var e=new BookEntity {Title=r.Title.Trim(),Author=r.Author.Trim(),Pages=r.Pages,TotalCopies=r.Copies,AvailableCopies=r.Copies}; db.Books.Add(e); await db.SaveChangesAsync(c.CancellationToken); return new BookReply{Book=Map(e)};
 }
 public override async Task<BookReply> GetBook(GetBookRequest r, ServerCallContext c) { var e=await db.Books.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==r.BookId,c.CancellationToken); return e is null?throw NotFound("Book not found."):new BookReply{Book=Map(e)}; }
 public override async Task<ListBooksReply> ListBooks(ListBooksRequest r, ServerCallContext c) { var page=Math.Max(1,r.Page); var size=Math.Clamp(r.PageSize==0?20:r.PageSize,1,100); var q=db.Books.AsNoTracking().OrderBy(x=>x.Title); return new ListBooksReply{TotalCount=await q.CountAsync(c.CancellationToken),Books={ (await q.Skip((page-1)*size).Take(size).ToListAsync(c.CancellationToken)).Select(Map)}}; }
 public override async Task<BorrowerReply> RegisterBorrower(RegisterBorrowerRequest r, ServerCallContext c) { if(string.IsNullOrWhiteSpace(r.Name)||string.IsNullOrWhiteSpace(r.Email)||!r.Email.Contains('@')) throw Invalid("A name and valid email are required."); var email=r.Email.Trim().ToLowerInvariant(); if(await db.Borrowers.AnyAsync(x=>x.Email==email,c.CancellationToken)) throw new RpcException(new Status(StatusCode.AlreadyExists,"A borrower with this email already exists.")); var e=new BorrowerEntity{Name=r.Name.Trim(),Email=email}; db.Borrowers.Add(e); await db.SaveChangesAsync(c.CancellationToken); return new BorrowerReply{Borrower=Map(e)}; }
 public override async Task<LoanReply> BorrowBook(BorrowBookRequest r, ServerCallContext c) { var book=await db.Books.SingleOrDefaultAsync(x=>x.Id==r.BookId,c.CancellationToken)??throw NotFound("Book not found."); if(!await db.Borrowers.AnyAsync(x=>x.Id==r.BorrowerId,c.CancellationToken)) throw NotFound("Borrower not found."); if(book.AvailableCopies<1) throw new RpcException(new Status(StatusCode.FailedPrecondition,"No copies are currently available.")); var at=r.BorrowedAt is null?DateTimeOffset.UtcNow:r.BorrowedAt.ToDateTimeOffset(); if(at> DateTimeOffset.UtcNow.AddMinutes(5)) throw Invalid("Borrowed date cannot be in the future."); book.AvailableCopies--; var loan=new LoanEntity{BookId=book.Id,BorrowerId=r.BorrowerId,BorrowedAt=at}; db.Loans.Add(loan); await db.SaveChangesAsync(c.CancellationToken); return new LoanReply{Loan=Map(loan)}; }
 public override async Task<LoanReply> ReturnBook(ReturnBookRequest r, ServerCallContext c) { var loan=await db.Loans.Include(x=>x.Book).SingleOrDefaultAsync(x=>x.Id==r.LoanId,c.CancellationToken)??throw NotFound("Loan not found."); if(loan.ReturnedAt is not null) throw new RpcException(new Status(StatusCode.FailedPrecondition,"This loan has already been returned.")); var at=r.ReturnedAt is null?DateTimeOffset.UtcNow:r.ReturnedAt.ToDateTimeOffset(); if(at<loan.BorrowedAt) throw Invalid("Return date cannot precede the borrow date."); loan.ReturnedAt=at; loan.Book!.AvailableCopies++; await db.SaveChangesAsync(c.CancellationToken); return new LoanReply{Loan=Map(loan)}; }
 public override async Task<BooksAnalyticsReply> GetMostBorrowedBooks(AnalyticsRequest r, ServerCallContext c) { var (from,to,limit)=Range(r.From,r.To,r.Limit); var rows=await db.Loans.AsNoTracking().Where(x=>x.BorrowedAt>=from&&x.BorrowedAt<=to).GroupBy(x=>x.BookId).Select(g=>new{Id=g.Key,Count=g.Count()}).OrderByDescending(x=>x.Count).ThenBy(x=>x.Id).Take(limit).ToListAsync(c.CancellationToken); var ids=rows.Select(x=>x.Id).ToArray(); var books=await db.Books.AsNoTracking().Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,c.CancellationToken); var reply=new BooksAnalyticsReply(); foreach(var row in rows) if(books.TryGetValue(row.Id,out var b)) reply.Results.Add(new BookStatistic{Book=Map(b),BorrowCount=row.Count}); return reply; }
 public override async Task<BorrowerActivityReply> GetMostActiveBorrowers(BorrowerActivityRequest r, ServerCallContext c) { var (from,to,limit)=Range(r.From,r.To,r.Limit); var rows=await db.Loans.AsNoTracking().Where(x=>x.BorrowedAt>=from&&x.BorrowedAt<=to).GroupBy(x=>x.BorrowerId).Select(g=>new{Id=g.Key,Count=g.Count()}).OrderByDescending(x=>x.Count).ThenBy(x=>x.Id).Take(limit).ToListAsync(c.CancellationToken); var ids=rows.Select(x=>x.Id).ToArray(); var users=await db.Borrowers.AsNoTracking().Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,c.CancellationToken); var reply=new BorrowerActivityReply(); foreach(var row in rows) if(users.TryGetValue(row.Id,out var u)) reply.Results.Add(new BorrowerStatistic{Borrower=Map(u),BorrowCount=row.Count}); return reply; }
 public override async Task<ReadingPaceReply> GetReadingPace(ReadingPaceRequest r, ServerCallContext c) { var loan=await db.Loans.AsNoTracking().Include(x=>x.Book).SingleOrDefaultAsync(x=>x.Id==r.LoanId,c.CancellationToken)??throw NotFound("Loan not found."); var end=loan.ReturnedAt??DateTimeOffset.UtcNow; var days=Math.Max((end-loan.BorrowedAt).TotalDays,1.0/24); return new ReadingPaceReply{LoanId=loan.Id,ElapsedDays=days,PagesPerDay=loan.Book!.Pages/days,Estimated=true}; }
 public override async Task<BooksAnalyticsReply> GetRelatedBooks(RelatedBooksRequest r, ServerCallContext c) { if(!await db.Books.AnyAsync(x=>x.Id==r.BookId,c.CancellationToken)) throw NotFound("Book not found."); var limit=Math.Clamp(r.Limit==0?10:r.Limit,1,100); var borrowerIds=db.Loans.Where(x=>x.BookId==r.BookId).Select(x=>x.BorrowerId).Distinct(); var rows=await db.Loans.AsNoTracking().Where(x=>x.BookId!=r.BookId&&borrowerIds.Contains(x.BorrowerId)).GroupBy(x=>x.BookId).Select(g=>new{Id=g.Key,Count=g.Count()}).OrderByDescending(x=>x.Count).ThenBy(x=>x.Id).Take(limit).ToListAsync(c.CancellationToken); var ids=rows.Select(x=>x.Id).ToArray(); var books=await db.Books.AsNoTracking().Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,c.CancellationToken); var reply=new BooksAnalyticsReply(); foreach(var row in rows) if(books.TryGetValue(row.Id,out var b)) reply.Results.Add(new BookStatistic{Book=Map(b),BorrowCount=row.Count}); return reply; }
 public override Task<HealthReply> Health(HealthRequest r, ServerCallContext c)=>Task.FromResult(new HealthReply{Status="Healthy"});
 private static (DateTimeOffset from,DateTimeOffset to,int limit) Range(Timestamp? f,Timestamp? t,int l) { var from=f is null?DateTimeOffset.MinValue:f.ToDateTimeOffset(); var to=t is null?DateTimeOffset.UtcNow:t.ToDateTimeOffset(); if(from>to) throw Invalid("The start date must be earlier than or equal to the end date."); return(from,to,Math.Clamp(l==0?10:l,1,100)); }
 private static Book Map(BookEntity x)=>new(){Id=x.Id,Title=x.Title,Author=x.Author,Pages=x.Pages,TotalCopies=x.TotalCopies,AvailableCopies=x.AvailableCopies}; private static Borrower Map(BorrowerEntity x)=>new(){Id=x.Id,Name=x.Name,Email=x.Email}; private static Loan Map(LoanEntity x){var m=new Loan{Id=x.Id,BookId=x.BookId,BorrowerId=x.BorrowerId,BorrowedAt=Timestamp.FromDateTimeOffset(x.BorrowedAt),IsReturned=x.ReturnedAt is not null}; if(x.ReturnedAt is not null)m.ReturnedAt=Timestamp.FromDateTimeOffset(x.ReturnedAt.Value); return m;}
 private static RpcException Invalid(string m)=>new(new Status(StatusCode.InvalidArgument,m)); private static RpcException NotFound(string m)=>new(new Status(StatusCode.NotFound,m));
}
